"""Outbound webhook delivery with token rotation."""

from auth.tokens import refresh_token


def handle_refresh(user_id: str) -> str:
    """Rotate the token for an expiring integration session."""
    return refresh_token(user_id)

"""Provider interfaces for credential checking."""

from abc import ABC, abstractmethod


class AuthProvider(ABC):
    """A strategy for verifying presented credentials."""

    @abstractmethod
    def authenticate(self, credentials: dict[str, str]) -> str:
        """Return the user id on success; raise InvalidCredentials on failure."""

    @abstractmethod
    def validate(self, code: str, context: dict[str, str] | None = None) -> bool:
        """Validate a secondary code, optionally with request context."""

"""Token rotation helper using an aliased import."""

from auth import tokens as tok


def rotate_now(user_id: str) -> str:
    """Rotate the integration token for ``user_id`` right now."""
    return tok.refresh_token(user_id)

"""SAML/SSO-style provider stub backed by assertion headers."""

from ..errors import InvalidCredentials
from ..interfaces import AuthProvider


class SsoAuthProvider(AuthProvider):
    """Authenticates via a trusted assertion header (fixture stub)."""

    def __init__(self, trusted_issuer: str) -> None:
        self._issuer = trusted_issuer

    def authenticate(self, credentials: dict[str, str]) -> str:
        assertion = credentials.get("assertion", "")
        if not assertion.startswith(self._issuer):
            raise InvalidCredentials("sso")
        return assertion_subject(assertion)

    def validate(self, code: str) -> bool:
        return len(code) == 8


def assertion_subject(assertion: str) -> str:
    """Extract the subject from an assertion string (fixture stub)."""
    return assertion.split("/", 1)[-1]
